import * as THREE from './assets/three.module.js';
import {createWalkingView} from './first-person.js?v=35';
import {blocked,BLOCKS} from './driving.mjs?v=35';
import {FURNITURE,WALLPAPERS} from './neighborhood-catalog.mjs?v=35';
export function createNeighbor(templates,avatar='jules') {
 const keys={jules:'suit',mina:'passenger-e',theo:'passenger-f',rae:'passenger-m'},source=templates[keys[avatar]]||templates.suit;
 const group=new THREE.Group(),root=source.scene.clone(true),size=new THREE.Box3().setFromObject(root),scale=1.8/size.getSize(new THREE.Vector3()).y;root.scale.setScalar(scale);root.position.y=-size.min.y*scale;group.add(root);
 const mixer=new THREE.AnimationMixer(root),actions=new Map();let current='',emoteUntil=0,emote='';
 function play(name){const clip=source.animations.find(c=>c.name===name)||source.animations.find(c=>c.name==='idle');if(!clip||current===clip.name)return;current=clip.name;for(const a of actions.values())a.fadeOut(.15);let action=actions.get(current);if(!action){action=mixer.clipAction(clip);actions.set(current,action);}action.reset().fadeIn(.15).play();}
 return {group,root,mixer,emote(id,until=Date.now()+3200){emote=id;emoteUntil=until;},update(dt,moving=false){const active=Date.now()<emoteUntil;play(active?(emote==='dance'?'walk':'emote-yes'):moving?'walk':'idle');mixer.update(dt);root.rotation.y=active&&emote==='dance'?Math.sin(Date.now()*.006)*.6:0;root.position.y=-size.min.y*scale+(active&&emote==='cheer'?Math.abs(Math.sin(Date.now()*.01))*.15:0);},dispose(){mixer.stopAllAction();mixer.uncacheRoot(root);group.removeFromParent();}};
}
export function createCityWalker(templates,world,camera){
 let person=createNeighbor(templates),avatar=person.group;const footBlocks=BLOCKS.filter(b=>!b.park),parks=BLOCKS.filter(b=>b.park),footBlocked=(x,z)=>blocked(x,z,.3,footBlocks)||parks.some(p=>Math.hypot(x-p.x,z-p.z)<1.9);let outfit='jules';avatar.visible=false;world.add(avatar);const walkingView=createWalkingView(camera,avatar),ray=new THREE.Raycaster(),plane=new THREE.Plane(new THREE.Vector3(0,1,0),-.17),point=new THREE.Vector3();let target=null;
 function spawn(x,z){target=null;for(let r=2;r<7;r+=1)for(let i=0;i<8;i++){const a=i*Math.PI/4,xx=x+Math.cos(a)*r,zz=z+Math.sin(a)*r;if(!footBlocked(xx,zz)){avatar.position.set(xx,.18,zz);avatar.visible=true;return;}}avatar.position.set(x,.18,z);avatar.visible=true;}
 function clickAt(x,y,w,h){ray.setFromCamera(new THREE.Vector2(x/w*2-1,1-y/h*2),camera);if(ray.ray.intersectPlane(plane,point)&&!footBlocked(point.x,point.z))target={x:point.x,z:point.z};}
 function update(dt,input){let d=walkingView.movement(input,dt);if(d.x||d.z)target=null;if(target){const dx=target.x-avatar.position.x,dz=target.z-avatar.position.z,len=Math.hypot(dx,dz);if(len<.25)target=null;else d={x:dx/len,z:dz/len};}const length=Math.hypot(d.x,d.z),speed=(input.sprint?6:3.8)*dt,old=avatar.position.clone();if(length){d.x/=length;d.z/=length;const x=avatar.position.x+d.x*speed,z=avatar.position.z+d.z*speed;if(!footBlocked(x,avatar.position.z))avatar.position.x=x;if(!footBlocked(avatar.position.x,z))avatar.position.z=z;avatar.rotation.y=Math.atan2(d.x,d.z);if(target&&old.distanceToSquared(avatar.position)<.00001)target=null;}avatar.position.y=parks.some(p=>Math.abs(avatar.position.x-p.x)<p.w/2&&Math.abs(avatar.position.z-p.z)<p.d/2)?.42:.18;person.update(dt,old.distanceToSquared(avatar.position)>.00001);if(walkingView.enabled)walkingView.update();else{camera.fov=48;camera.position.lerp(new THREE.Vector3(avatar.position.x+10,avatar.position.y+13,avatar.position.z+15),1-Math.exp(-dt*6));camera.lookAt(avatar.position.x,1,avatar.position.z);camera.updateProjectionMatrix();}}
 return {avatar,walkingView,spawn,update,clickAt,setFirstPerson:walkingView.set,look:walkingView.look,emote:(...args)=>person.emote(...args),setOutfit(id){if(outfit===id)return;outfit=id;const next=createNeighbor(templates,id);person.mixer.stopAllAction();avatar.remove(person.root);avatar.add(next.root);person=next;},hide(){avatar.visible=false;target=null;}};
}
const modelMap={'plant-small':'plantSmall1','chair-lounge':'loungeChairRelax','table-coffee':'tableCoffeeGlass','bookcase-closed':'bookcaseClosedDoors','lamp-standing':'lampRoundFloor','cardboardBox':'sideTable'};
function trophy(){const group=new THREE.Group(),gold=new THREE.MeshStandardMaterial({color:'#ecc466',metalness:.7,roughness:.28}),stone=new THREE.MeshStandardMaterial({color:'#244236',roughness:.8});for(const [w,h,d,y,mat]of [[.7,.18,.7,.09,stone],[.42,.12,.42,.24,gold],[.13,.42,.13,.5,gold],[.48,.1,.48,.74,gold],[.6,.12,.6,.85,gold],[.68,.12,.68,.97,gold]]){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),mat);m.position.y=y;group.add(m);}for(const x of [-.43,.43]){const m=new THREE.Mesh(new THREE.TorusGeometry(.2,.045,4,8),gold);m.position.set(x,.78,0);group.add(m);}return group;}
export function createPlacedFurniture(templates,apartment){
 const group=new THREE.Group();group.name='Player furniture';apartment.scene.add(group);let key='';const baseWalls=new Map();
 apartment.scene.traverse(o=>{if(o.isMesh&&o.geometry?.type==='BoxGeometry'){const p=o.geometry.parameters;if(p.height>.6&&(p.width>.9&&p.depth<.25||p.depth>.9&&p.width<.25))baseWalls.set(o,o.material.color?.clone());}});
 function apply(design){const next=JSON.stringify([design?.placements,design?.wallpaper]);const wallpaper=WALLPAPERS.find(w=>w.id===design?.wallpaper);for(const [wall,original]of baseWalls){if(wall.material.color){if(wallpaper)wall.material.color.set(wallpaper.color);else if(original)wall.material.color.copy(original);}}if(next===key)return;key=next;group.clear();for(let i=apartment.colliders.length-1;i>=0;i--)if(apartment.colliders[i].name==='player-furniture')apartment.colliders.splice(i,1);
  for(const p of design?.placements||[]){const item=FURNITURE.find(f=>f.id===p.id),template=templates['home-'+modelMap[item?.model]];if(!template)continue;const mesh=p.id==='crew-trophy'?trophy():template.scene.clone(true),bounds=new THREE.Box3().setFromObject(mesh),size=bounds.getSize(new THREE.Vector3()),center=bounds.getCenter(new THREE.Vector3()),scale=Math.min(item.width/Math.max(size.x,.01),item.depth/Math.max(size.z,.01));mesh.scale.setScalar(scale);mesh.position.set(-center.x*scale,-bounds.min.y*scale,-center.z*scale);const holder=new THREE.Group();holder.name=item.name;holder.position.set(p.x,.34,p.z);holder.rotation.y=p.rotation*Math.PI/2;holder.add(mesh);group.add(holder);
   const w=p.rotation%2?item.depth:item.width,d=p.rotation%2?item.width:item.depth;apartment.colliders.push({x:p.x,z:p.z,w,d,name:'player-furniture'});
  }

 }
 return {apply,group};
}
